/* Correction enrichie commune aux arènes : A contexte | B notions (cours en fenêtre) | C SSP et algorithme ; infobulles, sigles, prises en charge.
   Usage : <script src="correction.js" data-base="arenes/"></script> puis Correction.rendre(correction, echelle) → HTML. AAI (Anthropic AI) */
(function(){
const BASE=(document.currentScript&&document.currentScript.dataset.base)||'';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
let NOT={};
const NOMS={zeroD:"Zéro diagnostic",mechanism:"Mécanisme",semiology:"Sémiologie",discriminant:"Discriminant",decision:"Décision",trap:"Piège",anchor:"Ancre"};

let SIG={},RX=null;
fetch(BASE+'sigles.json').then(r=>r.json()).then(g=>{SIG=g;const k=Object.keys(g).sort((a,b)=>b.length-a.length).map(x=>x.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'));RX=new RegExp('(^|[^\\wÀ-ÿ])('+k.join('|')+')(?![\\wÀ-ÿ])','g');}).catch(()=>{});
const sig=h=>RX?h.replace(RX,(m,a,b)=>`${a}<abbr class="ab" data-i="${esc(b+' : '+SIG[b])}">${b}</abbr>`):h;
const T=x=>sig(esc(x));
function arbre(n,p){const e=n.e||[],id='a'+Math.random().toString(36).slice(2,8),ouvert=p<1;
 const cl=p===0?'racine':e.length?(ouvert?'':'ferme'):(n.pec?'pec':(n.notion?'feuille lien':'feuille'));
 return `<li><span class="noeud ${cl}" ${e.length?`data-a="${id}"`:''} ${n.pec?`data-pec="${n.pec}"`:''} ${n.i?`data-i="${esc(n.i)}"`:''} ${n.notion?`data-notion="${n.notion}"`:''}>${T(n.t)}${n.i?' <small>ⓘ</small>':''}</span>${e.length?`<ul ${ouvert?'':'hidden'} id="${id}">${e.map(x=>arbre(x,p+1)).join('')}</ul>`:''}</li>`;}
const cel=(x,k,j)=>Array.isArray(x)?x.map(o=>`<span class="hi ${j>=3&&k.length>4?(j===3?'d':'p'):(j===1?'d':'p')}" data-i="${esc(o.i)}" tabindex="0">${esc(o.t)}</span>`).join(' '):(x&&x.t?`<span class="hi d" data-i="${esc(x.i)}">${esc(x.t)}</span>`:T(x));
function tableau(t){const L=t.lignes;let h=`<table><thead><tr>${t.colonnes.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>`;
 L.forEach((l,r)=>{h+='<tr>';l.forEach((x,j)=>{if(j===0&&typeof x==='string'){if(r>0&&L[r-1][0]===x)return;let n=1;while(L[r+n]&&L[r+n][0]===x)n++;h+=`<td rowspan="${n}" class="cl">${esc(x)}</td>`;return;}
  const c=j===1&&t.colonnes.length>4?'sc':(j===2&&t.colonnes.length>4?'mol':'');h+=`<td class="${c}">${cel(x,t.colonnes,j)}</td>`;});h+='</tr>';});return h+'</tbody></table>';}
function pecHtml(P){const esc=T;const L=(a,f)=>(a||[]).map(f).join('');const v=c=>c?`<ul>${L(c.mesuresGenerales,x=>`<li>${esc(x)}</li>`)}</ul><ol class="etape">${L(c.etapes,e=>`<li><b>${esc(e.temps)}</b> · <span class="cl">${esc(e.qui)}</span> : ${esc(e.fait)}</li>`)}</ol>`:'';
 return `<div class="pecw"><h3>${esc(P.titre)}</h3><h4>But</h4><ul>${L(P.but,x=>`<li>${esc(x)}</li>`)}</ul>
 <h4>Moyens</h4><p class="ok">Mesures générales à l'accueil</p><ul>${L(P.moyens.accueil,x=>`<li>${esc(x)}</li>`)}</ul>
 ${P.moyens.pharmacologique.length?`<p class="ok">Pharmacologique</p><table><thead><tr><th>Molécule</th><th>Posologie</th><th>Pourquoi</th></tr></thead><tbody>${L(P.moyens.pharmacologique,m=>`<tr><td class="mol">${esc(m.molecule)}</td><td>${esc(m.posologie)}</td><td>${esc(m.pourquoi)}<div class="src">${esc(m.source)}</div></td></tr>`)}</tbody></table>`:''}
 <p class="ok">Non pharmacologique</p><ul>${L(P.moyens.nonPharmacologique,x=>`<li><span class="cl">${esc(x.categorie)}</span> : ${esc(x.mesure)}</li>`)}${L(P.moyens.transversal,x=>`<li><span class="cl">${esc(x.discipline)}</span> : ${esc(x.apport)}</li>`)}</ul>
 <h4>Conduite en équipe</h4><table><thead><tr><th>Situation d'urgence</th><th>Hors urgence</th></tr></thead><tbody><tr><td>${v(P.conduite.urgence)||'Sans objet'}</td><td>${v(P.conduite.horsUrgence)||'Sans objet'}</td></tr></tbody></table>
 ${P.cibles?`<h4>Cibles selon la forme</h4>${tableau(P.cibles)}`:''}
 <h4>Pronostic</h4><p>${esc(P.pronostic)}</p><h4>Surveillance</h4><table><thead><tr><th>Quoi</th><th>Quand</th><th>Cible</th></tr></thead><tbody>${L(P.surveillance.suivi,x=>`<tr><td class="mol">${esc(x.quoi)}</td><td>${esc(x.quand)}</td><td>${esc(x.cible)}</td></tr>`)}</tbody></table>
 <p><span class="cl">Sortie</span> : ${esc(P.surveillance.sortie)}</p><h4>Prévention</h4><ul>${['primaire','secondaire','tertiaire'].filter(k=>P.prevention[k]).map(k=>`<li><span class="cl">${k}</span> : ${esc(P.prevention[k])}</li>`).join('')}</ul></div>`;}
let PEC={};
function fenetre(n){const c=n.cours||{},t=c.tableau;$('fenetreCorps').innerHTML=`<button class="fermer" id="fermer">Fermer</button><h3>${esc(n.titre)}</h3><p>${T(n.comment)}</p>
 ${t?tableau(t):''}${c.arbre?`<p class="sous">Clique une case pour déplier ; survole ou touche-la pour lire le pourquoi.</p><div class="algo"><ul class="arbre">${arbre(c.arbre,0)}</ul></div>`:''}
 ${c.points?`<ul>${c.points.map(x=>`<li>${T(x)}</li>`).join('')}</ul>`:''}<p class="src">Sources : ${esc((n.sources||[]).join(' ; '))}</p>`;$('fenetre').classList.add('ouverte');$('fermer').onclick=()=>$('fenetre').classList.remove('ouverte');}
document.addEventListener('click',e=>{const b=e.target.closest('.notion');if(b&&NOT[b.dataset.n])fenetre(NOT[b.dataset.n]);
 const pz=e.target.closest('.noeud.pec');if(pz&&PEC[pz.dataset.pec]){$('fenetreCorps').innerHTML='<button class="fermer" id="fermer">Fermer</button>'+pecHtml(PEC[pz.dataset.pec]);$('fenetre').classList.add('ouverte');$('fermer').onclick=()=>$('fenetre').classList.remove('ouverte');}
 const ln=e.target.closest('.noeud[data-notion]');if(ln&&NOT[ln.dataset.notion]){fenetre(NOT[ln.dataset.notion]);return;}
 const hi=e.target.closest('[data-i]');if(hi){montrerBulle(hi);if(hi.classList.contains('hi'))return;}else $('bulle').style.display='none';
 const a=e.target.closest('.noeud');if(a&&a.dataset.a){const u=document.getElementById(a.dataset.a);if(u){u.hidden=!u.hidden;a.classList.toggle('ferme',u.hidden);}}
 if(e.target.id==='fenetre')$('fenetre').classList.remove('ouverte');});
function montrerBulle(el){const b=$('bulle');b.textContent=el.dataset.i;b.style.display='block';const r=el.getBoundingClientRect();
 let x=Math.min(r.left,innerWidth-350),y=r.bottom+8;if(y+b.offsetHeight>innerHeight)y=r.top-b.offsetHeight-8;b.style.left=Math.max(8,x)+'px';b.style.top=Math.max(8,y)+'px';}
document.addEventListener('mouseover',e=>{const hi=e.target.closest('[data-i]');if(hi)montrerBulle(hi);});document.addEventListener('mouseout',e=>{if(e.target.closest('[data-i]'))$('bulle').style.display='none';});

function rendre(c,echelle){NOT={};[...c.notions,...(c.autres||[])].forEach(n=>NOT[n.id]=n);PEC=c.pec||{};
 const ech=(echelle||[]).map(([m,t])=>`<dt>${NOMS[m]||m}</dt><dd>${T(t)}</dd>`).join(''),nb=(n,i,cl)=>`<button class="notion ${cl||''}" data-n="${n.id}"><b>${i}. ${esc(n.titre)}</b><span>${T(n.comment)}</span></button>`;
 return `<div class="deux"><div class="bloc"><h3>A · Le contexte expliqué</h3><dl class="echelle">${ech}</dl></div>
 <div class="bloc"><h3>B · Notions abordées</h3><div class="theme">Thème : ${esc(c.theme)}</div>${c.notions.map((n,i)=>nb(n,i+1)).join('')}
 ${c.autres&&c.autres.length?`<details><summary class="sous">Autres notions de la pathologie (${c.autres.length})</summary>${c.autres.map((n,i)=>nb(n,c.notions.length+i+1,'autre')).join('')}</details>`:''}</div></div>
 <div class="bloc ssp"><h3>C · Situation de départ : SSP ${esc(c.ssp.code)} « ${esc(c.ssp.nom)} »<span class="badge ${c.ssp.officiel?'':'add'}">${c.ssp.officiel?'SSP officiel PROFILES':'SSP additionnel'}</span></h3>
 <div class="sous">Algorithme décisionnel : clique une case pour déplier la suite.</div><div class="algo"><ul class="arbre">${arbre(c.ssp.algorithme,0)}</ul></div></div>`;}

const st=document.createElement('style');st.textContent=".sous{color:var(--sous);font-size:13px}\n.echelle{display:grid;grid-template-columns:150px 1fr;gap:6px 12px;background:var(--carte);border-radius:8px;padding:12px 14px;border:1px solid var(--trait);font-size:14px}\n.echelle dt{font-weight:700;color:var(--acc)}\n.echelle dd{margin:0}\n.src{font-size:12px;color:var(--sous);margin-top:8px}\n.echelle{grid-template-columns:1fr}\n.deux{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:18px}\n.bloc{background:var(--carte);border:1px solid var(--trait);border-radius:10px;padding:12px 14px}\n.bloc h3{font:700 15px Georgia,serif;margin:0 0 8px}\n.bloc .echelle{border:0;padding:0;grid-template-columns:118px 1fr;font-size:14px}\n.theme{font-weight:700;color:var(--acc);margin-bottom:6px}\n.notion{display:block;width:100%;text-align:left;font:inherit;color:inherit;background:transparent;border:1px solid var(--trait);border-radius:8px;padding:8px 10px;margin:6px 0;cursor:pointer}\n.notion:hover{border-color:var(--acc)}\n.notion b{display:block;font-size:14px}\n.notion span{font-size:13px;color:var(--sous)}\n.notion.autre{opacity:.75}\n.ssp{margin-top:14px}\n.badge{display:inline-block;font-size:12px;font-weight:700;padding:2px 9px;border-radius:99px;background:#1f8a4c;color:#fff;margin-left:6px}\n.badge.add{background:#b45309}\n.algo{overflow-x:auto;padding:8px 0}\n.arbre,.arbre ul{list-style:none;margin:0;padding:0;display:flex;align-items:center}\n.arbre li{display:flex;align-items:center;position:relative}\n.arbre ul{flex-direction:column;align-items:flex-start;padding-left:26px;position:relative}\n.arbre ul>li{padding:4px 0 4px 16px}\n.arbre ul>li::before{content:\"\";position:absolute;left:0;top:50%;width:16px;border-top:2px solid var(--acc)}\n.arbre ul>li::after{content:\"\";position:absolute;left:0;top:0;bottom:0;border-left:2px solid var(--acc)}\n.arbre ul>li:first-child::after{top:50%}\n.arbre ul>li:last-child::after{bottom:50%}\n.arbre ul>li:only-child::after{display:none}\n.arbre ul::before{content:\"\";position:absolute;left:0;top:50%;width:26px;border-top:2px solid var(--acc)}\n.noeud{background:var(--carte);border:1px solid var(--acc);border-radius:8px;padding:6px 10px;font-size:13px;max-width:210px;cursor:pointer;white-space:normal}\n.noeud.ferme::after{content:\" +\";color:var(--acc);font-weight:700}\n.noeud.feuille{border-style:dashed;cursor:default}\n.fenetre{position:fixed;inset:0;background:rgba(15,23,42,.45);display:none;align-items:center;justify-content:center;z-index:50;padding:16px}\n.fenetre.ouverte{display:flex}\n.fenetre>div{background:var(--carte);border-radius:12px;max-width:860px;width:100%;max-height:88vh;overflow:auto;padding:18px 20px}\n.fenetre h3{font:700 18px Georgia,serif;margin:0 0 6px}\n.fenetre table{width:100%;border-collapse:collapse;font-size:13.5px;margin:10px 0}\n.fenetre td,.fenetre th{border-bottom:1px solid var(--trait);padding:6px 8px;text-align:left;vertical-align:top}\n.fenetre th{color:var(--sous);font-size:12.5px}\n.fenetre li{margin:4px 0}\n.fermer{float:right;font:700 13px A;border:1px solid var(--trait);background:transparent;border-radius:99px;padding:4px 12px;cursor:pointer;color:var(--ink)}\n.deux{grid-template-columns:1fr}\n.arbre ul[hidden]{display:none!important}\n.arbre ul>li::before,.arbre ul>li::after,.arbre ul::before{border-color:#1d4ed8!important;border-width:2.5px!important}\n.noeud{border:1.5px solid #1d4ed8;color:#0f172a}\n.noeud.racine{background:#fde8ea;border-color:#c8102e;color:#9b0d23;font-weight:700}\n.noeud.feuille{border:1.5px dashed #64748b;cursor:default}\n.noeud.pec{min-width:200px;border:1.5px solid #c8102e;background:#fff5f5;cursor:pointer}\n.noeud.pec::after{content:\" \u25b8 prise en charge\";color:#c8102e;font-weight:700;font-size:12px}\n.fenetre table td,.fenetre table th{border:1px solid #a9bccd}\n.fenetre th{background:#f3f6f9;font-weight:700}\n.cl{font-weight:700;font-style:italic}\n.sc{font-weight:700}\n.mol{font-weight:400}\n.hi{display:block;margin:3px 0;cursor:help;text-decoration:underline dotted 1.5px;text-underline-offset:3px}\n.hi::before{content:'\u2022 '}\n.hi:hover,.hi:focus{color:#1d4ed8}\n#bulle{position:fixed;z-index:70;max-width:340px;background:#0f172a;color:#fff;font-size:13px;line-height:1.45;padding:10px 12px;border-radius:8px;box-shadow:0 8px 24px rgba(0,0,0,.25);display:none}\n.pecw h4{font:700 15px Georgia,serif;margin:14px 0 4px}\n.pecw .ok{font-weight:700;font-style:italic}\nabbr.ab{text-decoration:underline dotted 1px;text-underline-offset:2px;cursor:help}\n.noeud.lien{cursor:pointer}\n.noeud.lien::after{content:\" \u25b8 notion\";color:#1d4ed8;font-weight:700;font-size:12px}\n[hidden]{display:none!important}\n@media(max-width:760px){.deux{grid-template-columns:1fr}.echelle{grid-template-columns:1fr}}";document.head.appendChild(st);
function dom(){if($('bulle'))return;document.body.insertAdjacentHTML('beforeend','<div id="bulle" role="tooltip"></div><div class="fenetre" id="fenetre" role="dialog" aria-modal="true"><div id="fenetreCorps"></div></div>');}
if(document.body)dom();else document.addEventListener('DOMContentLoaded',dom);
window.Correction={rendre,MARCHES:NOMS};
})();
